 import { MatrixClient } from "matrix-js-sdk/src/client";
+import { logger } from "matrix-js-sdk/src/logger";

 import BasePlatform from "../../BasePlatform";
 import { IConfigOptions } from "../../IConfigOptions";
@@ -84,6 +85,37 @@ export const removeClientInformation = async (matrixClient: MatrixClient): Promi
 const sanitizeContentString = (value: unknown): string | undefined =>
     value && typeof value === "string" ? value : undefined;

+/**
+ * Removes client information events for devices that are no longer in the
+ * given list of device ids.
+ * This is best-effort maintenance and should not throw, callers should not
+ * need to await or handle errors from this.
+ * @todo(kerrya) revisit after MSC3391: account data deletion is done
+ * (PSBE-12)
+ */
+export const pruneClientInformation = async (deviceIds: string[], matrixClient: MatrixClient): Promise<void> => {
+    try {
+        const accountDataEvents = Object.values(matrixClient.store.accountData || {});
+        const clientInformationEventTypePrefix = getClientInformationEventType("");
+
+        const staleClientInformationEventTypes = accountDataEvents.reduce<string[]>((staleTypes, event) => {
+            const type = event.getType();
+            if (!type.startsWith(clientInformationEventTypePrefix)) {
+                return staleTypes;
+            }
+            const deviceId = type.slice(clientInformationEventTypePrefix.length);
+            if (!deviceIds.includes(deviceId)) {
+                staleTypes.push(type);
+            }
+            return staleTypes;
+        }, []);
+
+        await Promise.all(staleClientInformationEventTypes.map((type) => matrixClient.deleteAccountData(type)));
+    } catch (error) {
+        logger.error("Error removing stale client information", error);
+    }
+};
+
 export const getDeviceClientInformation = (matrixClient: MatrixClient, deviceId: string): DeviceClientInformation => {
     const event = matrixClient.getAccountData(getClientInformationEventType(deviceId));

