+Unless required by applicable law or agreed to in writing, software
+distributed under the License is distributed on an "AS IS" BASIS,
+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import { useEffect, useState } from "react";
+import { Room } from "matrix-js-sdk/src/models/room";
+import { RoomMember } from "matrix-js-sdk/src/models/room-member";
+import { MatrixEvent } from "matrix-js-sdk/src/models/event";
+import { logger } from "matrix-js-sdk/src/logger";
+
+import { MatrixClientPeg } from "../MatrixClientPeg";
+import { getPrimaryPermalinkEntity, parsePermalink } from "../utils/permalinks/Permalinks";
+import { PillType } from "../components/views/elements/Pill";
+
+interface Args {
+    // The Type of this Pill. If url is given, this is auto-detected.
+    type?: PillType;
+    // The URL to pillify (no validation is done)
+    url?: string;
+    // Whether the pill is in a message
+    inMessage?: boolean;
+    // The room in which this pill is being rendered
+    room?: Room;
+}
+
+interface Result {
+    // The type of pill that has been resolved from the props. Can differ from the `type`
+    // prop as it may be automatically detected from a permalink URL.
+    pillType?: PillType | string;
+    // The room related to the permalink, if applicable (room & @room pills).
+    room?: Room;
+    // The member related to the permalink, if applicable (user pills).
+    member?: RoomMember;
+    // The parsed resource ID from the permalink, e.g. a user or room ID/alias.
+    resourceId?: string;
+}
+
+/**
+ * Resolves a Pill's target (room, member, etc) based on the props passed to the Pill,
+ * doing any necessary profile/room lookups as required.
+ */
+export const usePermalink = ({ type, url, inMessage, room }: Args): Result => {
+    const [resourceId, setResourceId] = useState<string | undefined>();
+    const [targetRoom, setTargetRoom] = useState<Room | undefined>();
+    const [member, setMember] = useState<RoomMember | undefined>();
+    const [pillType, setPillType] = useState<PillType | string | undefined>(type);
+
+    useEffect(() => {
+        let unmounted = false;
+
+        let resource: string | undefined;
+        let prefix: string | undefined;
+
+        if (url) {
+            if (inMessage) {
+                const parts = parsePermalink(url);
+                resource = parts?.primaryEntityId ?? undefined; // The room/user ID
+                prefix = parts?.sigil; // The first character of the entity id
+            } else {
+                resource = getPrimaryPermalinkEntity(url) ?? undefined;
+                prefix = resource ? resource[0] : undefined;
+            }
+        }
+
+        const resolvedPillType =
+            type ??
+            ({
+                "@": PillType.UserMention,
+                "#": PillType.RoomMention,
+                "!": PillType.RoomMention,
+            }[prefix!] as PillType | undefined);
+
+        setResourceId(resource);
+        setPillType(resolvedPillType);
+        setTargetRoom(undefined);
+        setMember(undefined);
+
+        switch (resolvedPillType) {
+            case PillType.AtRoomMention: {
+                setTargetRoom(room);
+                break;
+            }
+            case PillType.UserMention: {
+                if (resource) {
+                    const localMember = room?.getMember(resource);
+                    if (localMember) {
+                        setMember(localMember);
+                    } else {
+                        const newMember = new RoomMember(null, resource);
+                        setMember(newMember);
+                        MatrixClientPeg.get()
+                            .getProfileInfo(resource)
+                            .then((resp) => {
+                                if (unmounted) return;
+                                const updatedMember = new RoomMember(null, resource);
+                                updatedMember.name = resp.displayname;
+                                updatedMember.rawDisplayName = resp.displayname ?? "";
+                                updatedMember.events.member = {
+                                    getContent: () => ({ avatar_url: resp.avatar_url }),
+                                    getDirectionalContent: function () {
+                                        return this.getContent();
+                                    },
+                                } as MatrixEvent;
+                                setMember(updatedMember);
+                            })
+                            .catch((err) => {
+                                logger.error("Could not retrieve profile data for " + resource + ":", err);
+                            });
+                    }
+                }
+                break;
+            }
+            case PillType.RoomMention: {
+                if (resource) {
+                    const foundRoom =
+                        resource[0] === "#"
+                            ? MatrixClientPeg.get()
+                                  .getRooms()
+                                  .find(
+                                      (r) =>
+                                          r.getCanonicalAlias() === resource || r.getAltAliases().includes(resource!),
+                                  )
+                            : MatrixClientPeg.get().getRoom(resource);
+                    setTargetRoom(foundRoom ?? undefined);
+                    // TODO: This would require a new API to resolve a room alias to
+                    // a room avatar and name.
+                    // doRoomProfileLookup(resourceId, member);
+                }
+                break;
+            }
+        }
+
+        return () => {
+            unmounted = true;
+        };
+        // eslint-disable-next-line react-hooks/exhaustive-deps
+    }, [type, url, inMessage, room]);
+
+    return {
+        pillType,
+        room: targetRoom,
+        member,
+        resourceId,
+    };
+};
