+
+import { arraySeed, arrayTrimFill } from "./arrays";
+
+/**
+ * An array which is fixed at a given length, always inserting new values
+ * at the start of the array and rolling off values at the end of the
+ * array. The array is seeded with a given value to fill unused slots.
+ */
+export class FixedRollingArray<T> {
+    private array: T[] = [];
+
+    public constructor(private width: number, private seed: T) {
+        this.array = arraySeed(this.seed, this.width);
+    }
+
+    public get value(): T[] {
+        return this.array;
+    }
+
+    public pushValue(value: T) {
+        this.array.splice(0, 0, value);
+        this.array = arrayTrimFill(this.array, this.width, arraySeed(this.seed, this.width));
+    }
+}
