new file mode 100644
index 0000000000..fea805ee4a
--- /dev/null
+++ b/src/utils/react.tsx
@@ -0,0 +1,64 @@
+/*
+Copyright 2024 New Vector Ltd.
+
+SPDX-License-Identifier: AGPL-3.0-only OR GPL-3.0-only
+Please see LICENSE files in the repository root for full details.
+*/
+
+import { type ReactNode } from "react";
+import { createRoot, type Root } from "react-dom/client";
+
+/**
+ * A small utility class to help manage the lifecycle of secondary React trees which are
+ * mounted outside of the main application tree, e.g. pills, tooltips, spoilers and code
+ * blocks which are dynamically injected into message bodies, exported HTML, and other
+ * places which do not otherwise participate in the React tree.
+ *
+ * This uses `createRoot` from `react-dom/client` under the hood, ensuring dynamic subtrees
+ * are compatible with React 18+ and are consistently mounted & unmounted, avoiding the need
+ * for manual bookkeeping of `ReactDOM.render`/`ReactDOM.unmountComponentAtNode` calls at the
+ * various call sites.
+ */
+export class ReactRootManager {
+    private roots = new Map<Element, Root>();
+
+    /**
+     * The DOM nodes which are currently the roots of a managed React tree, in the order
+     * they were first rendered into.
+     */
+    public get elements(): Element[] {
+        return Array.from(this.roots.keys());
+    }
+
+    /**
+     * The number of React roots currently being managed.
+     */
+    public get length(): number {
+        return this.roots.size;
+    }
+
+    /**
+     * Renders the given React node into the given container element.
+     * If the container has already been used with this manager then its existing root
+     * will be re-used, otherwise a new root will be created for it.
+     *
+     * @param node the React node to render
+     * @param container the DOM element to render into
+     */
+    public render(node: ReactNode, container: Element): void {
+        let root = this.roots.get(container);
+        if (!root) {
+            root = createRoot(container);
+            this.roots.set(container, root);
+        }
+        root.render(node);
+    }
+
+    /**
+     * Unmounts all the React roots managed by this instance and forgets about them.
+     */
+    public unmount(): void {
+        this.roots.forEach((root) => root.unmount());
+        this.roots.clear();
+    }
+}
